import { type } from "arktype"

const intBranch = type({
  kind: "'int'",
  value: "string"
}).morph((data) => ({
  kind: data.kind,
  value: Number(data.value)
}))

const rawBranch = type({
  kind: "'raw'",
  value: "string"
})

const PayloadSchema = type(intBranch, "or", rawBranch)

const res1 = PayloadSchema({ kind: "int", value: "42" })
console.log("res1:", res1)

const res2 = PayloadSchema({ kind: "raw", value: "42" })
console.log("res2:", res2)

const res3 = PayloadSchema({ kind: "other", value: "42" })
console.log("res3 is error:", res3 instanceof type.errors, res3)

